 using Microsoft.VisualStudio.TestTools.UnitTesting;
 using Contoso.Text;

 #nullable enable

 namespace Contoso.Text.Tests;

 [TestClass]
 public sealed class StringFormatterTests
 {
     private readonly StringFormatter _formatter = new();

     // ── FormatPhoneNumber ──────────────────────────────────────────

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ReturnsFormattedNumber()
     {
         var result = _formatter.FormatPhoneNumber("1234567890");

         Assert.AreEqual("(123) 456-7890", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_StartsWithAreaCode()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.StartsWith("(555)", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_EndsWithLastFour()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.EndsWith("4567", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ContainsDash()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.Contains("-", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_MatchesPattern()
     {
         var result = _formatter.FormatPhoneNumber("5551234567");

         Assert.MatchesRegex(@"^\(\d{3}\) \d{3}-\d{4}$", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_Null_ThrowsArgumentNullException()
     {
         var ex = Assert.ThrowsExactly<ArgumentNullException>(
             () => _formatter.FormatPhoneNumber(null!));
         Assert.AreEqual("digits", ex.ParamName);
     }

     [TestMethod]
     [DataRow("123", DisplayName = "Too short")]
     [DataRow("12345678901", DisplayName = "Too long")]
     [DataRow("", DisplayName = "Empty")]
     public void FormatPhoneNumber_WrongLength_ThrowsArgumentException(string digits)
     {
         Assert.ThrowsExactly<ArgumentException>(
             () => _formatter.FormatPhoneNumber(digits));
     }

     // ── BuildGreeting ──────────────────────────────────────────────

     [TestMethod]
     public void BuildGreeting_NameOnly_UsesDefaultTitle()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.StartsWith("Dear Mr.", result);
     }

     [TestMethod]
     public void BuildGreeting_NameOnly_EndsWithComma()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.EndsWith(",", result);
     }

     [TestMethod]
     public void BuildGreeting_NameAndTitle_ContainsName()
     {
         var result = _formatter.BuildGreeting("Jones", "Dr.");

         Assert.Contains("Jones", result);
     }

     [TestMethod]
     public void BuildGreeting_CustomTitle_ReturnsExpected()
     {
         var result = _formatter.BuildGreeting("Jones", "Dr.");

         Assert.AreEqual("Dear Dr. Jones,", result);
     }

     [TestMethod]
     public void BuildGreeting_NullName_ThrowsArgumentNullException()
     {
         Assert.ThrowsExactly<ArgumentNullException>(
             () => _formatter.BuildGreeting(null!));
     }

     [TestMethod]
     [DataRow("")]
     [DataRow("   ")]
     public void BuildGreeting_EmptyOrWhitespaceName_ThrowsArgumentException(string name)
     {
         Assert.ThrowsExactly<ArgumentException>(
             () => _formatter.BuildGreeting(name));
     }

     // ── GenerateSlug ───────────────────────────────────────────────

     [TestMethod]
     [DataRow("Hello World", "hello-world")]
     [DataRow("  Leading Spaces  ", "leading-spaces")]
     [DataRow("ALLCAPS", "allcaps")]
     [DataRow("special!!chars##here", "special-chars-here")]
     public void GenerateSlug_VariousInputs_ReturnsExpectedSlug(
         string title, string expected)
     {
         var result = _formatter.GenerateSlug(title);

         Assert.AreEqual(expected, result);
     }

     [TestMethod]
     public void GenerateSlug_Result_MatchesSlugPattern()
     {
         var result = _formatter.GenerateSlug("My Blog Post!!");

         Assert.MatchesRegex(@"^[a-z0-9]+(-[a-z0-9]+)*$", result);
     }

     [TestMethod]
     public void GenerateSlug_WhitespaceOnly_Throws()
     {
         Assert.ThrowsExactly<ArgumentException>(
             () => _formatter.GenerateSlug("   "));
     }

     // ── FormatCurrency ─────────────────────────────────────────────

     [TestMethod]
     public void FormatCurrency_DefaultSymbol_StartsWithDollar()
     {
         var result = _formatter.FormatCurrency(9.99m);

         Assert.StartsWith("$", result);
     }

     [TestMethod]
     public void FormatCurrency_CustomSymbol_StartsWithSymbol()
     {
         var result = _formatter.FormatCurrency(9.99m, "€");

         Assert.StartsWith("€", result);
     }

     [TestMethod]
     public void FormatCurrency_DefaultSymbol_EndsWithTwoDecimals()
     {
         var result = _formatter.FormatCurrency(5m);

         Assert.EndsWith(".00", result);
     }

     [TestMethod]
     public void FormatCurrency_WholeNumber_FormatsWithDecimals()
     {
         var result = _formatter.FormatCurrency(42m);

         Assert.AreEqual("$42.00", result);
     }

     [TestMethod]
     public void FormatCurrency_NegativeAmount_ContainsMinus()
     {
         var result = _formatter.FormatCurrency(-10.50m);

         Assert.Contains("-", result);
     }

     [TestMethod]
     [DataRow("$", 100.5, "$100.50")]
     [DataRow("£", 0.1, "£0.10")]
     [DataRow("¥", 1234.0, "¥1234.00")]
     public void FormatCurrency_VariousSymbols_ReturnsExpected(
         string symbol, double amount, string expected)
     {
         var result = _formatter.FormatCurrency((decimal)amount, symbol);

         Assert.AreEqual(expected, result);
     }
 }
